const fs = require('fs');
const ExcelJS = require('c:/Users/lg/resilient-bardeen/node_modules/exceljs');

async function applyPerfectMergedData() {
  const filePath = 'C:/Users/lg/Desktop/오늘/(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx';
  const tsvPath = 'c:/Users/lg/resilient-bardeen/merged_500_perfect.tsv';

  console.log('Loading merged TSV...');
  const lines = fs.readFileSync(tsvPath, 'utf-8').split('\n').filter(l => l.trim().length > 0);
  console.log('Total lines:', lines.length);

  console.log('Loading Excel workbook...');
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile(filePath);
  const sheet = workbook.getWorksheet('기업 정보');

  const orangeFill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FFFFA500' }
  };

  let updatedCount = 0;

  for (let i = 0; i < lines.length; i++) {
    const rowNum = 11847 + i;
    const row = sheet.getRow(rowNum);
    const p = lines[i].split('\t');

    // 0: author -> Col 1
    row.getCell(1).value = p[0];

    // 1: remark -> Col 2
    if (p[1]) {
      row.getCell(2).value = p[1];
    }

    // 2: company -> Col 3
    if (p[2]) {
      row.getCell(3).value = p[2];
    }

    // 3: bizno -> Col 4 with hyperlink
    const bizno = p[3].trim();
    if (bizno) {
      row.getCell(4).value = {
        text: bizno,
        hyperlink: 'https://bizno.net/article/' + bizno
      };
      row.getCell(4).font = { color: { argb: 'FF0000FF' }, underline: true };
    }

    // 4: ceo -> Col 5
    if (p[4]) {
      row.getCell(5).value = p[4];
    }

    // 5: zip -> Col 6 (Orange fill)
    if (p[5]) {
      row.getCell(6).value = p[5];
      row.getCell(6).fill = orangeFill;
    }

    // 6: address -> Col 7 (Orange fill)
    if (p[6]) {
      row.getCell(7).value = p[6];
      row.getCell(7).fill = orangeFill;
    }

    // 7: tel -> Col 8
    if (p[7]) {
      row.getCell(8).value = p[7];
      row.getCell(8).fill = orangeFill;
    }

    // 8: fax -> Col 9
    if (p[8]) {
      row.getCell(9).value = p[8];
      row.getCell(9).fill = orangeFill;
    }

    // 9: homepage -> Col 10
    if (p[9]) {
      row.getCell(10).value = p[9];
      row.getCell(10).fill = orangeFill;
    }

    // 10: email -> Col 11
    if (p[10]) {
      row.getCell(11).value = p[10];
      row.getCell(11).fill = orangeFill;
    }

    // 11: emp -> Col 15 (Orange fill)
    if (p[11]) {
      const empNum = !isNaN(p[11]) ? Number(p[11]) : p[11];
      row.getCell(15).value = empNum;
      row.getCell(15).fill = orangeFill;
    }

    // 12: nice -> Col 18 (Orange fill)
    if (p[12]) {
      row.getCell(18).value = p[12];
      row.getCell(18).fill = orangeFill;
    }

    // 13: corpNo -> Col 25 (Orange fill)
    if (p[13]) {
      row.getCell(25).value = p[13];
      row.getCell(25).fill = orangeFill;
    }

    // 14: settle -> Col 31 (Orange fill)
    if (p[14]) {
      row.getCell(31).value = p[14];
      row.getCell(31).fill = orangeFill;
    }

    // 15, 16, 17: categories -> Col 48, 49, 50 (Orange fill)
    if (p[15]) {
      row.getCell(48).value = p[15];
      row.getCell(48).fill = orangeFill;
    }
    if (p[16]) {
      row.getCell(49).value = p[16];
      row.getCell(49).fill = orangeFill;
    }
    if (p[17]) {
      row.getCell(50).value = p[17];
      row.getCell(50).fill = orangeFill;
    }

    row.commit();
    updatedCount++;
  }

  console.log('Successfully committed ' + updatedCount + ' rows to worksheet.');

  console.log('Writing to temporary file...');
  const tempPath = filePath + '.tmp';
  await workbook.xlsx.writeFile(tempPath);

  if (fs.existsSync(filePath)) {
    fs.unlinkSync(filePath);
  }
  fs.renameSync(tempPath, filePath);
  console.log('File successfully updated and replaced at:', filePath);

  // Also copy to repo
  const repoCopy = 'c:/Users/lg/resilient-bardeen/data/(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx';
  fs.copyFileSync(filePath, repoCopy);
  console.log('Synced to git repo data directory.');
}

applyPerfectMergedData().catch(console.error);
